import type { Question } from "../../types";

export const A1_AUTHORED_06: Question[] = [
  { id: "A1-AUTH-201", section: "A1", topic: "Anatomy", subtopic: "shoulder anatomy", difficulty: "foundational", text: "The glenohumeral joint is primarily classified as a:", options: ["Ball-and-socket synovial joint", "Hinge joint of the ankle", "Fibrous joint of the skull", "Saddle joint of the thumb"], correct: 0, explanation: "The glenohumeral joint is a ball-and-socket synovial joint that permits large movement at the cost of inherent bony stability.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-202", section: "A1", topic: "Anatomy", subtopic: "hip anatomy", difficulty: "foundational", text: "The primary muscle group producing hip extension during a powerful sprint stride is the:", options: ["Gluteal and hamstring group", "Wrist extensor group", "Rotator cuff group", "Anterior forearm group"], correct: 0, explanation: "Hip extensors contribute to propulsion, with their relative contribution varying by posture, speed and task technique.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-203", section: "A1", topic: "Anatomy", subtopic: "knee anatomy", difficulty: "foundational", text: "The anterior cruciate ligament primarily helps limit excessive:", options: ["Anterior translation of the tibia relative to the femur", "Elbow flexion", "Scapular elevation", "Ankle inversion only"], correct: 0, explanation: "The ACL contributes to restraint of anterior tibial translation and rotational control, although knee stability is multi-structure and task-dependent.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-204", section: "A1", topic: "Anatomy", subtopic: "ankle anatomy", difficulty: "foundational", text: "The talocrural joint primarily permits:", options: ["Dorsiflexion and plantarflexion", "Elbow pronation and supination", "Hip abduction and adduction only", "Cervical rotation"], correct: 0, explanation: "The talocrural joint contributes mainly to ankle dorsiflexion and plantarflexion, while subtalar motion contributes to foot inversion and eversion.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-205", section: "A1", topic: "Anatomy", subtopic: "foot mechanics", difficulty: "applied", text: "During running, the foot must provide both shock absorption and a relatively rigid lever. This illustrates:", options: ["Task-dependent changes in foot function", "A permanently locked foot", "The absence of muscle contribution", "A purely upper-limb mechanism"], correct: 0, explanation: "The foot adapts its mechanical behaviour across stance to manage impact and support propulsion.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-206", section: "A1", topic: "Anatomy", subtopic: "rotator cuff", difficulty: "foundational", text: "The rotator cuff contributes primarily to:", options: ["Dynamic glenohumeral control during shoulder movement", "Knee extension", "Ankle plantarflexion", "Spinal disc formation"], correct: 0, explanation: "The rotator cuff muscles contribute to glenohumeral centring and movement-specific control, not just isolated rotation.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-207", section: "A1", topic: "Anatomy", subtopic: "scapulohumeral rhythm", difficulty: "applied", text: "Efficient overhead elevation depends on coordination between the humerus and:", options: ["Scapular motion at the thorax", "The ankle mortise only", "The wrist bones only", "The lumbar discs only"], correct: 0, explanation: "Overhead movement is a coordinated kinetic-chain action involving glenohumeral and scapular-thoracic motion.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-208", section: "A1", topic: "Anatomy", subtopic: "trunk control", difficulty: "analytical", text: "A rower loses pelvic control when trunk extensor endurance falls late in a session. What does this suggest?", options: ["The kinetic chain and fatigue context should be addressed rather than isolating one muscle", "The spine is definitely injured", "Trunk endurance is irrelevant to rowing", "Only hamstring flexibility matters"], correct: 0, explanation: "Performance movement emerges from coordinated segments and fatigue tolerance; a visible change needs assessment rather than a single-tissue conclusion.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-209", section: "A1", topic: "Anatomy", subtopic: "nerve function", difficulty: "foundational", text: "Peripheral nerves carry information between the central nervous system and:", options: ["Muscles, skin and other tissues", "Only bone marrow", "Only the lungs", "Only tendons without receptors"], correct: 0, explanation: "Peripheral nerves transmit motor, sensory and autonomic information between the central nervous system and the body.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-210", section: "A1", topic: "Anatomy", subtopic: "proprioception", difficulty: "applied", text: "A gymnast closes her eyes and maintains a single-leg stance. Which sensory systems contribute to the task?", options: ["Vestibular, proprioceptive and remaining visual information", "Only the auditory system", "Only skin temperature", "No sensory input"], correct: 0, explanation: "Balance integrates visual, vestibular and somatosensory information; removing vision increases reliance on the others.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-211", section: "A1", topic: "Biomechanics", subtopic: "lever classes", difficulty: "foundational", text: "A lever's mechanical advantage depends substantially on the relationship between:", options: ["Effort and resistance moment arms", "Body mass and shoe size", "Heart rate and blood pressure", "Sleep and hydration only"], correct: 0, explanation: "Mechanical advantage is influenced by the relative moment arms of effort and resistance around the axis.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-212", section: "A1", topic: "Biomechanics", subtopic: "joint reaction force", difficulty: "analytical", text: "A deep squat changes hip and knee joint loading even when the external barbell mass is unchanged. Why?", options: ["Joint angles and moment arms alter internal and external torques", "Mass is the only determinant of torque", "Joint position cannot affect muscle demand", "The barbell becomes weightless"], correct: 0, explanation: "Posture changes moment arms and muscle lines of action, thereby changing joint moments and reaction forces.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-213", section: "A1", topic: "Biomechanics", subtopic: "horizontal impulse", difficulty: "applied", text: "To increase sprint acceleration, an athlete must generally increase the effective:", options: ["Horizontal component of net propulsive impulse", "Static shoulder range only", "Body mass without force change", "Recovery heart rate"], correct: 0, explanation: "Acceleration depends on net force and impulse in the relevant direction, subject to technique and ground-contact constraints.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-214", section: "A1", topic: "Biomechanics", subtopic: "ground contact", difficulty: "analytical", text: "A sprinter reduces ground-contact time but also produces less propulsive impulse. What is the correct interpretation?", options: ["Shorter contact is not automatically better; force and impulse must be considered together", "Shorter contact guarantees faster running", "Impulse is unrelated to acceleration", "Contact time alone determines technique"], correct: 0, explanation: "Performance depends on the force-time interaction and task velocity, not an isolated contact-time target.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-215", section: "A1", topic: "Biomechanics", subtopic: "moment of inertia", difficulty: "foundational", text: "An athlete can alter rotational difficulty by moving mass farther from the axis, which generally increases:", options: ["Moment of inertia", "Oxygen saturation", "Muscle glycogen", "Joint stability in every direction"], correct: 0, explanation: "Moment of inertia rises when mass is distributed farther from the axis, making angular acceleration more difficult for a given torque.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-216", section: "A1", topic: "Biomechanics", subtopic: "angular momentum", difficulty: "analytical", text: "A diver tucks during rotation and spins faster. The main mechanical explanation is:", options: ["Reducing moment of inertia while conserving angular momentum approximately", "Increasing body mass instantly", "Eliminating external torque in every situation", "Stopping all rotation"], correct: 0, explanation: "When external torque is limited, reducing moment of inertia can increase angular velocity while angular momentum is conserved approximately.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-217", section: "A1", topic: "Biomechanics", subtopic: "movement variability", difficulty: "analytical", text: "Why is some movement variability not automatically a sign of poor technique?", options: ["Adaptable variability can help an athlete respond to changing task and environmental demands", "All variability indicates injury", "Ideal technique is identical on every repetition", "Variability cannot be measured"], correct: 0, explanation: "Skilled performance includes adaptable solutions. Interpretation should consider task outcome, control, symptoms and context.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-218", section: "A1", topic: "Biomechanics", subtopic: "video analysis", difficulty: "applied", text: "Before comparing two slow-motion clips of a jump, the analyst should standardise:", options: ["Camera position, angle, distance, frame rate and task instructions", "Only the athlete's jersey", "The athlete's body mass", "The weather forecast only"], correct: 0, explanation: "Video comparisons are meaningful only when acquisition and task conditions are sufficiently consistent and documented.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-219", section: "A1", topic: "Biomechanics", subtopic: "measurement error", difficulty: "foundational", text: "A camera with low frame rate may make a fast movement appear:", options: ["Less precisely timed", "More clinically diagnosed", "More metabolically efficient", "Unrelated to motion"], correct: 0, explanation: "Insufficient temporal resolution can obscure event timing and introduce uncertainty in fast actions.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-220", section: "A1", topic: "Biomechanics", subtopic: "kinetic chain", difficulty: "applied", text: "A change in trunk position during a landing can alter knee demand because:", options: ["Segment positions change the centre of mass and joint moment arms", "The knee works independently of all segments", "Trunk position changes bone length immediately", "Landing forces disappear"], correct: 0, explanation: "Proximal segment position changes whole-body mechanics and can redistribute joint moments during landing.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-221", section: "A1", topic: "Exercise physiology", subtopic: "cardiac output", difficulty: "foundational", text: "Cardiac output is the product of:", options: ["Heart rate and stroke volume", "Blood pressure and body mass", "Respiratory rate and height", "Lactate and oxygen saturation"], correct: 0, explanation: "Cardiac output is heart rate multiplied by stroke volume and represents blood flow from the heart per unit time.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-222", section: "A1", topic: "Exercise physiology", subtopic: "stroke volume", difficulty: "applied", text: "During moderate endurance exercise, stroke volume may rise because of improved:", options: ["Ventricular filling and contractile function", "Bone length", "Skinfold thickness", "Joint laxity"], correct: 0, explanation: "Stroke volume reflects filling and ejection; training adaptations can improve cardiovascular function, although responses vary by person and intensity.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-223", section: "A1", topic: "Exercise physiology", subtopic: "Fick principle", difficulty: "analytical", text: "The Fick principle relates oxygen consumption to cardiac output and:", options: ["The arterial-venous oxygen difference", "Joint range of motion", "Muscle circumference only", "The number of repetitions"], correct: 0, explanation: "VO2 equals cardiac output multiplied by the arterial-venous oxygen difference, linking circulation and tissue extraction.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-224", section: "A1", topic: "Exercise physiology", subtopic: "blood pressure", difficulty: "applied", text: "During dynamic exercise, systolic blood pressure generally rises because:", options: ["Cardiac output increases", "All peripheral vessels constrict equally", "Heart rate falls to zero", "Muscle blood flow stops"], correct: 0, explanation: "Dynamic exercise usually increases cardiac output and systolic pressure, while local vascular responses vary across tissues.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-225", section: "A1", topic: "Exercise physiology", subtopic: "autonomic recovery", difficulty: "applied", text: "Heart-rate recovery after exercise is often used as an indicator related to:", options: ["Autonomic recovery and cardiovascular fitness context", "Tendon structure directly", "Body composition alone", "Joint stability"], correct: 0, explanation: "Heart-rate recovery provides information about post-exercise autonomic response but should be standardised and interpreted clinically.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-226", section: "A1", topic: "Exercise physiology", subtopic: "ventilation", difficulty: "foundational", text: "Minute ventilation is calculated from respiratory rate multiplied by:", options: ["Tidal volume", "Body mass index", "Heart rate", "Joint torque"], correct: 0, explanation: "Minute ventilation is the volume of air moved per minute and equals respiratory frequency times tidal volume.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-227", section: "A1", topic: "Exercise physiology", subtopic: "oxygen saturation", difficulty: "analytical", text: "A pulse-oximeter reading falls during exercise. What is the most appropriate immediate interpretation?", options: ["Check signal quality, symptoms, protocol and medical context before concluding there is pathological desaturation", "Assume the number is exact", "Continue maximal exercise regardless of symptoms", "Diagnose anemia from the reading"], correct: 0, explanation: "Device signal and context matter. Concerning readings or symptoms require appropriate clinical assessment rather than a remote diagnosis.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-228", section: "A1", topic: "Exercise physiology", subtopic: "energy expenditure", difficulty: "foundational", text: "The energy cost of exercise is affected by intensity, duration and:", options: ["Exercise mode and individual efficiency", "Only the athlete's height", "Only the colour of the surface", "Nothing beyond heart rate"], correct: 0, explanation: "Energy expenditure depends on the task, duration, intensity and individual mechanical and metabolic efficiency.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-229", section: "A1", topic: "Exercise physiology", subtopic: "muscle fibre", difficulty: "foundational", text: "Type II muscle fibres are generally associated with greater capacity for:", options: ["High-force and high-power actions", "Long-duration low-force work only", "Passive joint motion", "Thermal insulation"], correct: 0, explanation: "Type II fibres generally have higher force and power potential, although fibre behaviour and performance depend on training and task.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-230", section: "A1", topic: "Exercise physiology", subtopic: "muscle hypertrophy", difficulty: "applied", text: "A reasonable resistance-training stimulus for hypertrophy should consider:", options: ["Sufficient mechanical tension, volume, recovery and progressive overload", "Only the heaviest possible single repetition", "No nutritional support", "Identical loading for every athlete"], correct: 0, explanation: "Hypertrophy is influenced by accumulated training stimulus and recovery; prescriptions should be individualised and progressed.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-231", section: "A1", topic: "Exercise physiology", subtopic: "neuromuscular adaptation", difficulty: "analytical", text: "Early strength gains in a novice may occur before large muscle-size changes because of:", options: ["Neural and motor-learning adaptations", "Immediate tendon lengthening", "Loss of all inhibition", "A change in body height"], correct: 0, explanation: "Early training can improve neural drive, coordination and skill, while structural adaptations develop over a longer period.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-232", section: "A1", topic: "Exercise physiology", subtopic: "recovery interval", difficulty: "applied", text: "Longer recovery intervals between maximal sprints generally allow greater restoration of:", options: ["Performance capacity for the next sprint", "Joint laxity", "Bone mass within seconds", "The athlete's height"], correct: 0, explanation: "Recovery duration influences phosphagen restoration, fatigue and the ability to maintain sprint output.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-233", section: "A1", topic: "Exercise physiology", subtopic: "concurrent training", difficulty: "analytical", text: "When strength and endurance sessions compete for recovery, programming should consider:", options: ["Order, spacing, total load and the athlete's primary performance goal", "Only the duration of the warm-up", "A universal schedule for all sports", "Ignoring one training mode"], correct: 0, explanation: "Concurrent training requires management of session order, interference, recovery and sport priorities.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-234", section: "A1", topic: "Exercise physiology", subtopic: "training specificity", difficulty: "foundational", text: "Training specificity means that adaptations are influenced strongly by:", options: ["The mode, intensity, duration and movement demands trained", "The athlete's favourite colour", "A single general fitness score", "Resting height alone"], correct: 0, explanation: "Adaptations are specific to the stimuli applied, so training should include qualities and tasks relevant to the target sport.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-235", section: "A1", topic: "Exercise physiology", subtopic: "progressive overload", difficulty: "foundational", text: "Progressive overload requires the training stimulus to:", options: ["Increase or change appropriately as the athlete adapts", "Remain maximal every day", "Decrease regardless of response", "Be identical across all phases"], correct: 0, explanation: "Overload is planned relative to adaptation and recovery; it can change through load, volume, speed, complexity or density.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-236", section: "A1", topic: "Exercise physiology", subtopic: "tapering", difficulty: "applied", text: "A taper typically aims to reduce fatigue while preserving:", options: ["Relevant fitness and intensity exposure", "All movement", "Only body mass", "The athlete's injury risk at zero"], correct: 0, explanation: "Tapering reduces training load to dissipate fatigue while retaining selected intensity and sport-specific stimulus.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-237", section: "A1", topic: "Exercise physiology", subtopic: "warm-up", difficulty: "foundational", text: "A warm-up is most likely to be useful when it is:", options: ["Specific to the upcoming task and sufficient to prepare without excessive fatigue", "As exhausting as the main event", "Identical for every athlete and sport", "Used instead of technical practice"], correct: 0, explanation: "Warm-ups should prepare temperature, movement, coordination and intensity while preserving performance capacity.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-238", section: "A1", topic: "Exercise physiology", subtopic: "cool-down", difficulty: "foundational", text: "The most defensible description of a cool-down is that it may:", options: ["Provide a gradual transition and opportunity for low-intensity movement, but is not a cure-all", "Prevent every delayed soreness episode", "Remove all metabolic by-products instantly", "Replace recovery sleep"], correct: 0, explanation: "A cool-down can be comfortable and practical, but claims that it prevents all soreness or replaces recovery are not justified.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-239", section: "A1", topic: "Exercise physiology", subtopic: "oxygen consumption", difficulty: "applied", text: "Excess post-exercise oxygen consumption describes elevated oxygen use:", options: ["After exercise as the body returns toward baseline", "Only before a warm-up", "During sleep without any prior activity", "Only when oxygen is absent"], correct: 0, explanation: "EPOC reflects recovery processes after exercise; its size depends on the intensity and duration of the preceding work.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-240", section: "A1", topic: "Exercise physiology", subtopic: "fat oxidation", difficulty: "analytical", text: "At a low-to-moderate intensity, fat oxidation may contribute substantially to energy supply, but the exact contribution depends on:", options: ["Intensity, duration, nutrition, training status and individual response", "Only body mass", "Only the athlete's age", "The number of stretching exercises"], correct: 0, explanation: "Substrate use is dynamic and influenced by workload, nutrition and individual physiology; no single factor determines it.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-241", section: "A1", topic: "Biochemistry", subtopic: "ATP", difficulty: "foundational", text: "ATP is important in muscle because it:", options: ["Provides immediately usable chemical energy for cellular work", "Stores all body oxygen", "Forms the outer skin layer", "Is the same molecule as collagen"], correct: 0, explanation: "ATP supplies energy for cross-bridge cycling, ion pumps and other cellular processes, with continuous resynthesis required.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-242", section: "A1", topic: "Biochemistry", subtopic: "phosphocreatine", difficulty: "foundational", text: "Phosphocreatine supports rapid ATP resynthesis by donating:", options: ["A phosphate group to ADP", "Oxygen to haemoglobin", "Calcium to bone", "Collagen to tendon"], correct: 0, explanation: "The phosphagen system transfers a high-energy phosphate to ADP, rapidly reforming ATP during short intense efforts.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-243", section: "A1", topic: "Biochemistry", subtopic: "glycolysis", difficulty: "foundational", text: "Glycolysis breaks down glucose or glycogen to support ATP production in the:", options: ["Cytosol", "Joint capsule only", "Lung alveoli only", "Bone cortex only"], correct: 0, explanation: "Glycolysis occurs in the cytosol and can rapidly contribute ATP, with pyruvate and lactate handling depending on metabolic conditions.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-244", section: "A1", topic: "Biochemistry", subtopic: "mitochondria", difficulty: "foundational", text: "Mitochondria are central to:", options: ["Oxidative ATP production", "Ligament testing", "Skinfold measurement", "Joint lubrication only"], correct: 0, explanation: "Mitochondria use oxidative pathways to produce ATP, particularly important for sustained and repeated exercise.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-245", section: "A1", topic: "Biochemistry", subtopic: "lactate clearance", difficulty: "applied", text: "Blood lactate can fall during recovery because lactate is:", options: ["Oxidised, converted or transported for use by other tissues", "Always trapped permanently in muscle", "Identical to carbon dioxide", "Produced only when exercise stops"], correct: 0, explanation: "Lactate is a usable metabolic intermediate and its concentration reflects production, transport and clearance across tissues.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-246", section: "A1", topic: "Biochemistry", subtopic: "acid-base", difficulty: "analytical", text: "Why should blood lactate not be described simply as the cause of all exercise fatigue?", options: ["Fatigue is multifactorial and lactate concentration reflects several production and clearance processes", "Lactate is never present during exercise", "Fatigue is always psychological", "Lactate is the same as muscle glycogen"], correct: 0, explanation: "Exercise fatigue involves neural, metabolic, mechanical and perceptual factors; a blood lactate value cannot represent them all.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-247", section: "A1", topic: "Biochemistry", subtopic: "protein turnover", difficulty: "applied", text: "Resistance exercise can increase muscle protein synthesis, but adaptation also depends on:", options: ["Nutrition, recovery, training dose and repeated exposure", "Only one post-exercise meal", "Avoiding all endurance activity", "The athlete's height only"], correct: 0, explanation: "Adaptation reflects the interaction of exercise, amino-acid availability, recovery and the longer-term training programme.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-248", section: "A1", topic: "Biochemistry", subtopic: "iron status", difficulty: "analytical", text: "An endurance athlete with fatigue and low ferritin should be advised to:", options: ["Seek appropriate clinical evaluation rather than self-prescribe high-dose iron", "Take unlimited iron immediately", "Ignore the result", "Use ferritin as a diagnosis of overtraining"], correct: 0, explanation: "Iron findings require clinical interpretation, assessment of cause and appropriate treatment; unsupervised supplementation can be harmful.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-249", section: "A1", topic: "Biochemistry", subtopic: "inflammation", difficulty: "applied", text: "An elevated inflammatory marker after a hard training session should be interpreted with:", options: ["Training history, symptoms, recovery and clinical context", "A guaranteed diagnosis of infection", "No context because the marker is definitive", "Only the athlete's sprint time"], correct: 0, explanation: "Inflammatory markers can change after exercise and illness; isolated results should not be overinterpreted.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-250", section: "A1", topic: "Biochemistry", subtopic: "hydration physiology", difficulty: "foundational", text: "The principal physiological challenge of substantial fluid loss during prolonged exercise is reduced:", options: ["Plasma volume and thermoregulatory or cardiovascular reserve", "Bone length", "Tendon collagen immediately", "Joint range in every direction"], correct: 0, explanation: "Fluid loss can reduce plasma volume and strain cardiovascular and thermal regulation, with effects depending on environment and individual response.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-251", section: "A1", topic: "Training theory", subtopic: "supercompensation", difficulty: "analytical", text: "Why should the supercompensation model not be used as a precise prediction for every athlete?", options: ["Adaptation and fatigue vary with stimulus, recovery, health and individual response", "Training never causes adaptation", "All athletes recover on the same schedule", "It applies only to flexibility"], correct: 0, explanation: "Simple models can aid teaching but cannot replace monitoring and individualised programming across complex training blocks.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-252", section: "A1", topic: "Training theory", subtopic: "recovery", difficulty: "foundational", text: "Recovery is best understood as the process of restoring:", options: ["Physical, physiological, psychological and performance capacity", "Only muscle length", "Only body mass", "Only motivation"], correct: 0, explanation: "Recovery is multidimensional and includes the ability to tolerate and perform subsequent training and competition.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-253", section: "A1", topic: "Training theory", subtopic: "monotony", difficulty: "applied", text: "A programme with identical high training loads every day may be problematic because it offers little:", options: ["Variation and recovery opportunity", "Specificity", "Data collection", "Exercise selection"], correct: 0, explanation: "Excessive monotony can reduce recovery and adaptability. Planned variation should match the season and athlete response.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-254", section: "A1", topic: "Training theory", subtopic: "individualisation", difficulty: "foundational", text: "Individualisation of training means that prescription should account for:", options: ["The athlete's capacities, goals, sport, health and response", "Only team averages", "A universal age-based table", "The coach's preference alone"], correct: 0, explanation: "Individualisation adapts dose and progression to the person while preserving the demands of the sport and programme.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-255", section: "A1", topic: "Training theory", subtopic: "periodisation", difficulty: "applied", text: "A competition calendar should influence periodisation because it changes:", options: ["The timing and priority of training stress, recovery and peak performance", "The athlete's anatomy", "Whether monitoring is needed", "The definition of an injury"], correct: 0, explanation: "Training organisation should reflect the timing and importance of competitions, travel, recovery and performance goals.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-256", section: "A1", topic: "Training theory", subtopic: "deload", difficulty: "applied", text: "A planned deload is used primarily to:", options: ["Reduce accumulated fatigue while retaining selected movement and skill exposure", "Remove all training forever", "Guarantee a personal record", "Increase fatigue before every competition"], correct: 0, explanation: "A deload can lower volume or stress to support recovery while preserving useful technical or intensity exposure.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-257", section: "A1", topic: "Training theory", subtopic: "readiness", difficulty: "analytical", text: "An athlete feels ready but shows reduced force and altered movement after illness. What should guide training?", options: ["The combined evidence should prompt caution, recovery and possible medical review", "Subjective readiness always overrides objective data", "Objective data always diagnose disease", "Maximal training should proceed"], correct: 0, explanation: "Conflicting readiness information requires discussion and context; recent illness and altered function justify a cautious plan.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-258", section: "A1", topic: "Training theory", subtopic: "adherence", difficulty: "foundational", text: "The most sustainable home programme is usually one that is:", options: ["Understandable, feasible, meaningful and adjusted to barriers", "As long as possible", "Identical for every athlete", "Based on punishment"], correct: 0, explanation: "Adherence improves when the plan is clear, manageable and linked to the athlete's goals and circumstances.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-259", section: "A1", topic: "Training theory", subtopic: "feedback", difficulty: "applied", text: "Effective performance feedback is most likely to be:", options: ["Specific, timely, actionable and linked to the agreed task", "Only negative", "Delayed until the season ends", "A comparison with unrelated athletes"], correct: 0, explanation: "Specific feedback helps the athlete understand what to change and how to practise it within the task context.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-260", section: "A1", topic: "Training theory", subtopic: "coaching communication", difficulty: "analytical", text: "A physiotherapist and coach disagree about progressing a returning athlete. The best next step is to:", options: ["Review shared criteria, data, athlete goals and risk assumptions together", "Let the loudest person decide", "Hide the disagreement from the athlete", "Progress immediately to avoid delay"], correct: 0, explanation: "Transparent multidisciplinary reasoning improves consistency and allows the athlete's informed goals and uncertainties to be addressed.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-261", section: "A1", topic: "Assessment", subtopic: "sensitivity", difficulty: "foundational", text: "Sensitivity is the proportion of people with a condition who have a:", options: ["Positive test", "Negative test", "Normal body mass", "High performance score"], correct: 0, explanation: "Sensitivity is the true-positive rate and is useful when considering how well a test detects people who have the condition.", source: "Diagnostic test performance methods", sourceKind: "research" },
  { id: "A1-AUTH-262", section: "A1", topic: "Assessment", subtopic: "specificity", difficulty: "foundational", text: "Specificity is the proportion of people without a condition who have a:", options: ["Negative test", "Positive test", "High training load", "Pain response"], correct: 0, explanation: "Specificity is the true-negative rate and helps describe a test's ability to correctly classify people without the condition.", source: "Diagnostic test performance methods", sourceKind: "research" },
  { id: "A1-AUTH-263", section: "A1", topic: "Assessment", subtopic: "likelihood ratio", difficulty: "analytical", text: "A positive likelihood ratio is useful because it helps estimate how much a positive test changes:", options: ["The probability of a condition", "The athlete's maximal strength", "The amount of fluid lost", "The number of repetitions"], correct: 0, explanation: "Likelihood ratios combine test characteristics with pre-test probability to update the probability of a condition.", source: "Diagnostic test performance methods", sourceKind: "research" },
  { id: "A1-AUTH-264", section: "A1", topic: "Assessment", subtopic: "pre-test probability", difficulty: "analytical", text: "Why does disease prevalence affect interpretation of the same screening test?", options: ["It changes the pre-test probability and therefore the predictive meaning of results", "Prevalence changes the test apparatus", "Prevalence never matters", "It changes the athlete's height"], correct: 0, explanation: "Predictive values depend on the underlying probability of the condition in the tested population.", source: "Diagnostic test performance methods", sourceKind: "research" },
  { id: "A1-AUTH-265", section: "A1", topic: "Assessment", subtopic: "measurement error", difficulty: "foundational", text: "Technical error of measurement is most relevant when deciding whether a small change is:", options: ["Likely beyond expected measurement noise", "Always a true adaptation", "A diagnosis of pathology", "A change in motivation only"], correct: 0, explanation: "Measurement error provides context for interpreting small differences and supports decisions about repeat testing.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-266", section: "A1", topic: "Assessment", subtopic: "ceiling effect", difficulty: "analytical", text: "A test with a ceiling effect may fail to show improvement because:", options: ["Participants already score near the maximum", "The test always measures injury", "The athlete cannot learn", "The test has no scoring system"], correct: 0, explanation: "When scores cluster near the maximum, meaningful improvement may be hidden even if capacity changes.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "A1-AUTH-267", section: "A1", topic: "Assessment", subtopic: "floor effect", difficulty: "analytical", text: "A floor effect occurs when:", options: ["Scores cluster near the minimum and deterioration or improvement is difficult to detect", "Everyone reaches maximal performance", "The test is too specific", "There is no measurement error"], correct: 0, explanation: "A floor effect limits discrimination at the lower end of a scale and can obscure meaningful change.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "A1-AUTH-268", section: "A1", topic: "Assessment", subtopic: "responsiveness", difficulty: "applied", text: "A responsive outcome measure should be able to detect:", options: ["Meaningful change when it occurs in the target population", "Only stable scores", "Any change regardless of error", "The exact tissue lesion"], correct: 0, explanation: "Responsiveness concerns detecting change over time; the change must still be interpreted against error and clinical importance.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "A1-AUTH-269", section: "A1", topic: "Assessment", subtopic: "clinical prediction", difficulty: "analytical", text: "A clinical prediction rule should be applied only when:", options: ["Its population, variables and intended decision fit the athlete's context", "The rule is popular online", "The athlete has no symptoms", "It replaces professional judgement"], correct: 0, explanation: "Prediction rules are context-specific tools and require appropriate population, measurement and decision use.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "A1-AUTH-270", section: "A1", topic: "Assessment", subtopic: "triangulation", difficulty: "foundational", text: "Triangulation in athlete monitoring means:", options: ["Combining complementary data sources to improve interpretation", "Repeating one flawed measure indefinitely", "Using only subjective data", "Choosing the highest score"], correct: 0, explanation: "Triangulation combines symptoms, performance, workload and clinical findings to reduce overreliance on a single measure.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-271", section: "A1", topic: "Technology", subtopic: "wearables", difficulty: "analytical", text: "Before using a wearable-derived workload metric for clinical decisions, the team should verify:", options: ["Validity, reliability, data quality and relevance to the decision", "Only the device's marketing claims", "That every athlete has the same signal", "That missing data are ignored"], correct: 0, explanation: "Technology is useful only when its measurements and limitations are understood and the metric addresses a meaningful question.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-272", section: "A1", topic: "Technology", subtopic: "missing data", difficulty: "applied", text: "An athlete's GPS file is missing the final 20 minutes. What should the analyst do?", options: ["Flag the missing data and avoid comparing the incomplete total directly with complete files", "Treat the total as complete", "Fill the gap with the team average without disclosure", "Delete all season data"], correct: 0, explanation: "Missingness can bias workload estimates. It should be documented and handled transparently before interpretation.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-273", section: "A1", topic: "Technology", subtopic: "data security", difficulty: "foundational", text: "A wearable platform should not be used as the sole source of medical clearance because:", options: ["It provides limited context and cannot replace clinical assessment", "It always overestimates speed", "It cannot record any movement", "Medical clearance never needs examination"], correct: 0, explanation: "Wearable data can inform monitoring but cannot establish diagnosis, readiness or clearance without appropriate clinical reasoning.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-274", section: "A1", topic: "Technology", subtopic: "video privacy", difficulty: "analytical", text: "A training video includes identifiable athletes and is requested by an external vendor. What is required before sharing?", options: ["Appropriate permission, data protection and a clear purpose for the disclosure", "Automatic sharing because it is sport footage", "Removal of the medical record only", "Posting it publicly first"], correct: 0, explanation: "Identifiable video is personal data. Sharing should follow consent, governance, security and purpose-limitation principles.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-275", section: "A1", topic: "Technology", subtopic: "algorithmic bias", difficulty: "analytical", text: "A risk algorithm performs worse in athletes from one subgroup. What should the team do?", options: ["Audit performance across groups and avoid using it as an unquestioned decision-maker", "Use it more aggressively", "Hide the subgroup results", "Assume all models are unbiased"], correct: 0, explanation: "Models require validation in relevant populations and should not automate high-stakes decisions without scrutiny and human oversight.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-276", section: "A1", topic: "Technology", subtopic: "dashboard design", difficulty: "applied", text: "A useful athlete dashboard should prioritise:", options: ["Clear definitions, actionable variables, trends and uncertainty", "Every possible metric on one screen", "Colour without labels", "A single red-green decision"], correct: 0, explanation: "Good dashboards support interpretation and action by showing relevant trends, definitions and limitations without unnecessary cognitive load.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-277", section: "A1", topic: "Technology", subtopic: "calibration", difficulty: "foundational", text: "Calibration of a force platform is important because it helps ensure:", options: ["Recorded forces correspond appropriately to known inputs", "The athlete becomes stronger", "The platform predicts injury", "The test needs no instructions"], correct: 0, explanation: "Calibration links instrument output to known values and supports measurement accuracy before data interpretation.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-278", section: "A1", topic: "Technology", subtopic: "data literacy", difficulty: "foundational", text: "A data dictionary is useful because it records:", options: ["Variable definitions, units, coding rules and missing-data conventions", "Only the athlete's nickname", "Unverified conclusions", "The next competition result"], correct: 0, explanation: "A data dictionary makes collection and interpretation consistent across analysts, time points and systems.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-279", section: "A1", topic: "Technology", subtopic: "interpretability", difficulty: "analytical", text: "A complex model predicts injury but cannot explain its inputs. How should it be used?", options: ["With caution, transparent validation and human review rather than automatic clearance decisions", "As an unquestionable diagnosis", "Without checking data quality", "Only after deleting all clinical information"], correct: 0, explanation: "Opaque prediction models require validation, governance and cautious communication, especially for high-stakes athlete decisions.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-280", section: "A1", topic: "Technology", subtopic: "reporting", difficulty: "applied", text: "A performance report is most actionable when it ends with:", options: ["A concise interpretation, limitations and agreed next steps", "A list of unexplained numbers", "A definitive injury prediction", "No recommendation because data speak for themselves"], correct: 0, explanation: "Decision-makers need context, limitations and practical next steps, while uncertainty and the source of evidence remain visible.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
];
